package gal.rodrigosambade.locationlab;
import android.Manifest;import android.app.PendingIntent;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*;import androidx.activity.result.*;import androidx.activity.result.contract.ActivityResultContracts;import androidx.appcompat.app.AppCompatActivity;import androidx.core.content.ContextCompat;import com.google.android.gms.location.*;import java.util.*;
public class MainActivity extends AppCompatActivity{
 FusedLocationProviderClient fused;GeofencingClient geofencing;ActivityRecognitionClient activity;TextView status;android.location.Location last;ActivityResultLauncher<String[]> perms=registerForActivityResult(new ActivityResultContracts.RequestMultiplePermissions(),r->status.setText("Permisos actualizados"));
 protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);status=findViewById(R.id.status);fused=LocationServices.getFusedLocationProviderClient(this);geofencing=LocationServices.getGeofencingClient(this);activity=ActivityRecognition.getClient(this);findViewById(R.id.location).setOnClickListener(v->locate());findViewById(R.id.geofence).setOnClickListener(v->geofence());findViewById(R.id.activity).setOnClickListener(v->activities());findViewById(R.id.settings).setOnClickListener(v->startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS, Uri.parse("package:"+getPackageName()))));request();}
 void request(){List<String> m=new ArrayList<>();if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)m.add(Manifest.permission.ACCESS_FINE_LOCATION);if(Build.VERSION.SDK_INT>=29&&ContextCompat.checkSelfPermission(this,Manifest.permission.ACTIVITY_RECOGNITION)!=PackageManager.PERMISSION_GRANTED)m.add(Manifest.permission.ACTIVITY_RECOGNITION);if(!m.isEmpty())perms.launch(m.toArray(new String[0]));}
 boolean locPerm(){return ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED;}boolean actPerm(){return Build.VERSION.SDK_INT<29||ContextCompat.checkSelfPermission(this,Manifest.permission.ACTIVITY_RECOGNITION)==PackageManager.PERMISSION_GRANTED;}
 void locate(){if(!locPerm()){request();return;}fused.getCurrentLocation(Priority.PRIORITY_HIGH_ACCURACY,null).addOnSuccessListener(l->{last=l;status.setText(l==null?"Sin fix":"Lat "+l.getLatitude()+"\nLon "+l.getLongitude()+"\n±"+l.getAccuracy()+" m");}).addOnFailureListener(e->status.setText(e.toString()));}
 PendingIntent geoPi(){return PendingIntent.getBroadcast(this,100,new Intent(this,GeofenceReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);}void geofence(){if(!locPerm()){request();return;}if(last==null){locate();return;}Geofence g=new Geofence.Builder().setRequestId("demo-200m").setCircularRegion(last.getLatitude(),last.getLongitude(),200).setExpirationDuration(3600000).setTransitionTypes(Geofence.GEOFENCE_TRANSITION_ENTER|Geofence.GEOFENCE_TRANSITION_EXIT).build();GeofencingRequest q=new GeofencingRequest.Builder().setInitialTrigger(GeofencingRequest.INITIAL_TRIGGER_ENTER).addGeofence(g).build();geofencing.addGeofences(q,geoPi()).addOnSuccessListener(v->status.setText("Geofence registrado 1 h")).addOnFailureListener(e->status.setText(e.toString()));}
 PendingIntent actPi(){return PendingIntent.getBroadcast(this,101,new Intent(this,ActivityTransitionReceiver.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);}void activities(){if(!actPerm()){request();return;}List<ActivityTransition> l=new ArrayList<>();for(int t:new int[]{DetectedActivity.WALKING,DetectedActivity.RUNNING,DetectedActivity.ON_BICYCLE,DetectedActivity.IN_VEHICLE})for(int x:new int[]{ActivityTransition.ACTIVITY_TRANSITION_ENTER,ActivityTransition.ACTIVITY_TRANSITION_EXIT})l.add(new ActivityTransition.Builder().setActivityType(t).setActivityTransition(x).build());activity.requestActivityTransitionUpdates(new ActivityTransitionRequest(l),actPi()).addOnSuccessListener(v->status.setText("Transiciones registradas; mira Logcat")).addOnFailureListener(e->status.setText(e.toString()));}
}
